objectives.normalized_solution_structure:
excel:{
  "operation": "import",
  "delimiter": ",",
  "headers": true,
  "table": "orders",
  "types": {
    "order_date": "date",
    "revenue": "number"
  }
}

excel:{
  "operation": "pivot",
  "group_by": [
    "city",
    "category"
  ],
  "measure": "SUM(orders[revenue])"
}

excel:{
  "operation": "formula",
  "formula": "=[@quantity]*[@price]-[@discount]"
}

excel:{
  "operation": "format",
  "column": "status",
  "equals": "Отменён",
  "style": "red"
}

excel:{
  "operation": "kpis",
  "measures": {
    "revenue": "SUM(orders[revenue])",
    "orders_count": "COUNTA(orders[order_id])",
    "average_order": "AVERAGE(orders[revenue])"
  }
}

excel:{
  "operation": "filter",
  "filters": {
    "channel": "Сайт",
    "city": "Москва"
  }
}

excel:{
  "operation": "measure",
  "measures": {
    "average_order": "SUM(orders[revenue])/COUNTA(orders[order_id])"
  }
}

excel:{
  "operation": "quality",
  "columns": [
    "rating",
    "order_id",
    "order_date"
  ]
}

excel:{
  "operation": "insight",
  "claims": [
    {
      "metric": "top_city",
      "value": "Волгоград"
    },
    {
      "metric": "revenue",
      "value": 385000
    }
  ]
}

power-bi:{
  "operation": "import",
  "types": {
    "order_date": "date",
    "revenue": "number",
    "order_id": "number",
    "is_new_customer": "boolean"
  }
}

power-bi:{
  "operation": "cards",
  "measures": {
    "revenue": "SUM(orders[revenue])",
    "orders_count": "COUNTROWS(orders)"
  }
}

power-bi:{
  "operation": "bar",
  "group_by": [
    "city"
  ],
  "visual": "bar",
  "measure": "SUM(orders[revenue])"
}

power-bi:{
  "operation": "slicer",
  "filters": {
    "channel": "Приложение"
  }
}

power-bi:{
  "operation": "measure",
  "measures": {
    "average_order": "DIVIDE(SUM(orders[revenue]),COUNTROWS(orders))"
  }
}

power-bi:{
  "operation": "delivery",
  "filters": {
    "status": "Оплачен"
  },
  "group_by": "city",
  "visual": "bar"
}

power-bi:{
  "operation": "interactions",
  "selected_city": "Москва",
  "interaction": "filter"
}

power-bi:{
  "operation": "status",
  "group_by": [
    "status"
  ],
  "visual": "bar",
  "measure": "SUM(orders[revenue])"
}

power-bi:{
  "operation": "insights",
  "claims": [
    {
      "metric": "top_city",
      "value": "Волгоград"
    },
    {
      "metric": "cancelled_orders",
      "value": 2
    },
    {
      "metric": "top_channel",
      "value": "Магазин"
    }
  ]
}
